let palette;
let graphics;
let cellStates = [];
let cells = 6;

function setup() {
  createCanvas(800, 800);
  angleMode(DEGREES);
  graphics = createGraphics(width, height);
  graphics.colorMode(HSB, 360, 100, 100, 100);
  graphics.noStroke();

  for (let i = 0; i < (width * height * 10) / 100; i++) {
    graphics.fill(0, 0, 100, 5);
    let x = random(width);
    let y = random(height);
    let w = random(3);
    let h = random(3);
    graphics.ellipse(x, y, w, h);
  }

  // 初始化單元格狀態，便於動態追蹤
  for (let k = 0; k < cells; k++) {
    for (let j = 0; j < cells; j++) {
      cellStates.push({
        shape_num: int(random(2)),
        rotBase: (int(random(4)) * 360) / 4,
        speedMult: random(0.5, 1.8)
      });
    }
  }
}

function draw() {
  let beatVal = window.beatEnergy || 0.0;
  let audioVal = window.audioLow || 0.5;

  clear();
  background(15, 12, 10); // 深色背景

  // 獲取並混入當前和弦色彩
  palette = chromotome.get().colors.slice();
  if (window.currentChordColor) {
    palette.unshift(window.currentChordColor);
  }

  let iMax = min(palette.length, 6);
  let rotSpeed = frameCount * (0.4 + audioVal * 1.8);

  for (let i = 0; i < iMax; i++) {
    let g = createGraphics(width, height);
    g.angleMode(DEGREES);
    let c1 = palette[i % palette.length];
    let c2 = palette[(i + 1) % palette.length];
    let c3 = palette[(i + 2) % palette.length];
    var r = sqrt(sq(width) + sq(height)) / 2;

    // 漸變隨時間旋轉
    let gAngle = (frameCount * 0.15 + (i * 360) / iMax) % 360;
    let x1 = width / 2 + cos(gAngle) * r;
    let y1 = height / 2 + sin(gAngle) * r;
    let x2 = width / 2 + cos(gAngle + 180) * r;
    let y2 = height / 2 + sin(gAngle + 180) * r;

    let arr = [c1, c2, c3];
    let gradient = g.drawingContext.createLinearGradient(x1, y1, x2, y2);
    gradient.addColorStop(0.0, arr[0]);
    gradient.addColorStop(0.5, arr[1]);
    gradient.addColorStop(1.0, arr[2]);

    g.drawingContext.fillStyle = gradient;
    g.noStroke();
    g.rect(0, 0, width, height);

    if (i != 0) {
      g.push();
      g.erase(255, 255);
      g.noStroke();

      let off = width / 12;
      let margin = 4;
      let d = int((width - off * 2 - margin * (cells - 1)) / cells);

      let idx = 0;
      for (let k = 0; k < cells; k++) {
        for (let j = 0; j < cells; j++) {
          let state = cellStates[idx % cellStates.length];
          idx++;

          let dx = int(off + j * (d + margin) + d / 2);
          let dy = int(off + k * (d + margin) + d / 2);

          g.push();
          g.translate(dx, dy);

          // 變種特點: 單元格形狀會隨音樂旋轉
          g.rotate(state.rotBase + rotSpeed * state.speedMult);

          // 變種特點: 縮放大小受重拍脈動
          let scaleFactor = (i / (iMax - 1)) * (0.7 + beatVal * 0.45);

          switch (state.shape_num) {
            case 0:
              g.translate(-d / 2, -d / 2);
              g.scale(scaleFactor);
              g.arc(0, 0, d * 2, d * 2, 0, 90);
              break;
            case 1:
              g.translate(-d / 2, -d / 2);
              g.scale(scaleFactor);
              g.triangle(0, 0, d, 0, d, d);
              break;
          }
          g.pop();
        }
      }
      g.noErase();
      g.pop();
    }

    blendMode(SCREEN); // 變種為濾色混合，適合霓虹發光
    drawingContext.shadowColor = color(palette[i % palette.length]);
    drawingContext.shadowBlur = width / 25 * (0.8 + beatVal * 1.5);
    image(g, 0, 0);
  }

  blendMode(ADD);
  image(graphics, 0, 0);
  blendMode(BLEND);
}

